function validExtensions(v){const pt=p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1;return (!v.paths||(Array.isArray(v.paths)&&v.paths.length<=100&&v.paths.every(p=>typeof p.id==='string'&&MATERIALS[p.material]&&Number.isFinite(p.width)&&p.width>=.5&&p.width<=20&&Array.isArray(p.points)&&p.points.length>=2&&p.points.length<=100&&p.points.every(pt))))&&(!v.zip||/^\d{5}$/.test(v.zip))&&(!v.quotes||(Array.isArray(v.quotes)&&v.quotes.length<=300&&v.quotes.every(q=>q&&typeof q.key==='string'&&typeof q.signature==='string'&&/^\d{5}$/.test(q.zip)&&Number.isFinite(q.amount)&&q.amount>=0&&q.amount<=1e8&&typeof q.source==='string'&&q.source.length<=200&&['materials','installed'].includes(q.scope)&&/^\d{4}-\d{2}-\d{2}$/.test(q.date)&&(!q.url||/^https?:\/\//.test(q.url))))) }
function segmentDistance(p,a,b){const dx=(b.x-a.x)*S.width,dy=(b.y-a.y)*S.depth,px=(p.x-a.x)*S.width,py=(p.y-a.y)*S.depth,t=Math.max(0,Math.min(1,(px*dx+py*dy)/(dx*dx+dy*dy||1)));return Math.hypot(px-t*dx,py-t*dy)}
function pathLength(p){return p.points.slice(1).reduce((sum,v,j)=>sum+Math.hypot((v.x-p.points[j].x)*S.width,(v.y-p.points[j].y)*S.depth),0)}
function pointInItem(p,i){const theta=-i.angle*Math.PI/180,dx=(p.x-i.x)*S.width,dy=(p.y-i.y)*S.depth,x=dx*Math.cos(theta)-dy*Math.sin(theta),y=dx*Math.sin(theta)+dy*Math.cos(theta);return CATALOG[i.kind].round?x*x/(i.w*i.w/4)+y*y/(i.h*i.h/4)<=1:Math.abs(x)<=i.w/2&&Math.abs(y)<=i.h/2}
let surfaceCache={key:'',value:null};
function surfaceAreas(){const key=JSON.stringify([S.points,S.shape,S.curve,S.width,S.depth,S.zones,S.paths,S.material,S.items.filter(i=>CATALOG[i.kind].occupies)]);if(surfaceCache.key===key)return surfaceCache.value;const border=borderSamples(),area=areaOf(border),n=120,buckets={},built=S.items.filter(i=>CATALOG[i.kind].occupies);let total=0;for(let y=0;y<n;y++)for(let x=0;x<n;x++){const p={x:(x+.5)/n,y:(y+.5)/n};if(!inside(p,border))continue;total++;let kind='base';if(built.some(i=>pointInItem(p,i)))kind='occupied';else{const path=[...S.paths].reverse().find(r=>r.points.slice(1).some((b,j)=>segmentDistance(p,r.points[j],b)<=r.width/2));if(path)kind='path:'+path.material;else if(S.zones.some(z=>inside(p,z.points)))kind='soil'}buckets[kind]=(buckets[kind]||0)+1}for(const k in buckets)buckets[k]=total?buckets[k]/total*area:0;return surfaceCache={key,value:{area,buckets}},surfaceCache.value}
function scopeSignature(key,qty){return JSON.stringify([key,qty])}
function quoteFor(row){return S.quotes.find(q=>q.key===row.key&&q.zip===S.zip&&q.signature===row.signature)}
