if(base>.01)add('ground:'+S.material,MATERIALS[S.material].name,base.toFixed(1)+' sq ft','Base ground · '+rateLabel(MATERIALS[S.material].rate)+'/sq ft + 10% allowance',base*MATERIALS[S.material].rate*1.1,base.toFixed(2));
for(const k in buckets)if(k.startsWith('path:')){const m=k.slice(5),v=buckets[k];add(k,MATERIALS[m].name+' paths',v.toFixed(1)+' sq ft','Path surface · '+rateLabel(MATERIALS[m].rate)+'/sq ft + 10% allowance',v*MATERIALS[m].rate*1.1,v.toFixed(2))}
