function catalogPicker(step){const groups=step===2?PLANT_GROUPS:step===3?BUILD_GROUPS:null,available=Object.entries(CATALOG).filter(([k,c])=>step===2?c.type==='plant':step===3?c.type!=='plant'&&c.type!=='light':c.type==='light');if(groups&&catalogGroup!=='all'&&!groups[catalogGroup])catalogGroup='all';const matches=available.filter(([k,c])=>(!groups||catalogGroup==='all'||c.group===catalogGroup)&&(!catalogSearch||c.name.toLowerCase().includes(catalogSearch.toLowerCase())));return `${groups?`<label class="field">Browse ${step===2?'planting':'garden elements'}<select id="catalog-group"><option value="all">All ${step===2?'planting':'elements'} (${available.length})</option>${Object.entries(groups).map(([k,n])=>`<option value="${k}" ${catalogGroup===k?'selected':''}>${n} (${available.filter(([,c])=>c.group===k).length})</option>`).join('')}</select></label>`:''}<p class="note">${step===2?'These are design choices, not confirmed nursery stock. Only sourced care notes are shown; climate, cultivar and stock still need checking.':'Choose an element, then edit its measured footprint. Built structures and water features remain quote-required.'}</p><div class="catalog expanded-catalog">${matches.map(([k,c])=>`<button data-add="${k}">${catalogThumb(k)}<span>${c.name}</span><small>${c.price===null?'Quote required':money(c.price)+' · demo'}</small></button>`).join('')}</div>`}
function pathTools(){return `<details class="path-tools" ${tool==='path'?'open':''}><summary>Paths & walkways (${S.paths.length})</summary><label class="field">Path finish<select id="path-material">${Object.entries(MATERIALS).map(([k,m])=>`<option value="${k}" ${pathMaterial===k?'selected':''}>${m.name}</option>`).join('')}</select></label><label class="field">Path width · ft<input id="path-width" type="number" min=".5" max="20" step=".5" value="${pathWidth}"></label><button class="outline-btn ${tool==='path'?'active-tool':''}" id="draw-path">+ Draw a walkway</button><button class="text-btn" id="straight-path">+ Start with a straight path</button>${tool==='path'&&draft.length?'<button class="outline-btn" id="finish-draw">Finish walkway ✓</button><button class="text-btn" id="cancel-draw">Cancel drawing</button>':''}<p class="note">Tap the route, then finish. Surface quantities are clipped to the garden. Newer paths replace older paths where they overlap.</p>${S.paths.map(p=>`<button class="text-btn" data-path-select="${esc(p.id)}">${esc(p.name)} · ${pathLength(p).toFixed(1)} ft ↗</button>`).join('')}</details>`}
function bindPathTools(){if(!$('#draw-path'))return;$('#path-material').onchange=e=>pathMaterial=e.target.value;$('#path-width').onchange=e=>pathWidth=clamp(+e.target.value||3,.5,20);$('#straight-path').onclick=()=>change(()=>{const p={id:uid(),name:'Walkway '+(S.paths.length+1),material:pathMaterial,width:pathWidth,points:[{x:.1,y:.5},{x:.9,y:.5}]};S.paths.push(p);selection={type:'path',id:p.id};tool='select'},{controls:true});$('#draw-path').onclick=()=>{tool='path';draft=[];selection=null;renderAll(true);notify('Tap at least 2 points for the walkway, then finish.')};$$('[data-path-select]').forEach(b=>b.onclick=()=>{selection={type:'path',id:b.dataset.pathSelect};tool='select';renderAll()})}
function utilityTools(){return `<p class="sub-label">UNDER THE SURFACE</p><label class="field">Service<select id="route-kind">${Object.entries(UTILITY_TYPES).map(([k,u])=>`<option value="${k}" ${routeKind===k?'selected':''}>${u.name}</option>`).join('')}</select></label><label class="field">Record status<select id="route-state">${Object.entries(ROUTE_STATES).map(([k,n])=>`<option value="${k}" ${routeState===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Source / survey / ticket reference<input id="route-reference" type="text" maxlength="160" value="${esc(routeReference)}" placeholder="Required for source-recorded lines"></label><div class="draw-tools"><button class="outline-btn ${tool==='route'?'active-tool':''}" id="draw-route">+ Draw a service route</button>${tool==='route'&&draft.length?'<button class="outline-btn" id="finish-draw">Finish route ✓</button><button class="text-btn" id="cancel-draw">Cancel drawing</button>':''}</div><p class="note">This records requirements and approximate routes, not trench depth, pipe sizing or construction details. <a class="source-link" href="https://www.enbridge.com/projects-and-infrastructure/public-awareness/safe-digging-and-damage-prevention/call-811" target="_blank" rel="noopener">Locate utilities before digging ↗</a></p><details class="utility-layers" open><summary>Visible service layers</summary>${Object.entries(UTILITY_TYPES).map(([k,u])=>`<label class="switch-label"><input type="checkbox" data-layer="${k}" ${routeVisibility[k]===false?'':'checked'}><i style="background:${u.color}"></i>${u.name}</label>`).join('')}</details>${S.routes.map(r=>`<button class="text-btn" data-route-item="${esc(r.id)}">${esc(UTILITY_TYPES[r.kind]?.name||r.kind)} · ${esc(ROUTE_STATES[r.status]||'Unverified')} ↗</button>`).join('')}`}
function bindUtilityTools(){if(!$('#draw-route'))return;$('#route-state').onchange=e=>routeState=e.target.value;$('#route-reference').oninput=e=>routeReference=e.target.value;$('#draw-route').onclick=()=>{if(routeState==='verified'&&!routeReference.trim()){notify('Add a survey or source reference before recording an existing line with a source.');$('#route-reference').focus();return}tool='route';selection=null;draft=[];renderAll(true);notify('Tap at least 2 points to record this service route.')};$$('[data-layer]').forEach(inp=>inp.onchange=()=>{routeVisibility[inp.dataset.layer]=inp.checked;renderCanvas()});$$('[data-route-item]').forEach(b=>b.onclick=()=>{selection={type:'route',id:b.dataset.routeItem};renderAll()})}
function locationFields(context='studio'){return `<div class="zip-fields" data-zip-context="${context}"><label class="field">Your US ZIP code<input class="zip-input" inputmode="numeric" maxlength="5" pattern="[0-9]{5}" placeholder="e.g. 10001" value="${esc(S.zip)}" aria-label="${context} ZIP code"></label><button class="outline-btn zip-lookup" ${zipLoading?'disabled':''}>${zipLoading?'Looking up…':'Set quote location ↗'}</button><div class="zip-result" role="status">${esc(zipMessage|| (S.location&&S.location.zip===S.zip?S.location.city+', '+S.location.state+' · '+S.zip:S.zip?'ZIP '+S.zip+' · place not verified':'Add a ZIP to organize local quotes.'))}</div><p class="note">Your ZIP is sent to <a href="https://docs.zippopotam.us/docs/getting-started/" target="_blank" rel="noopener" class="source-link">Zippopotam.us</a> for city/state lookup. It does not provide prices or plant hardiness. Supplier pricing is not connected.</p></div>`}
function bindLocationFields(){document.querySelectorAll('.zip-lookup').forEach(b=>b.onclick=()=>lookupZip(b.closest('.zip-fields').querySelector('.zip-input').value))}
async function lookupZip(raw){const zip=raw.trim();if(!/^\d{5}$/.test(zip)){zipMessage='Enter a five-digit US ZIP code.';refreshLocation();return}zipAbort?.abort();const controller=new AbortController();zipAbort=controller;zipLoading=true;zipMessage='Looking up the city and state…';change(()=>{if(S.zip!==zip)S.location=null;S.zip=zip});refreshLocation();const timeout=setTimeout(()=>controller.abort(),10000);try{const res=await fetch('https://api.zippopotam.us/us/'+zip,{signal:controller.signal,referrerPolicy:'no-referrer'});if(!res.ok)throw Error(res.status===404?'notfound':'network');const data=await res.json(),place=data.places?.[0];if(!place||data['post code']!==zip)throw Error('notfound');if(S.zip!==zip)return;S.location={zip,city:place['place name'],state:place['state abbreviation'],source:'Zippopotam.us / GeoNames',checked:new Date().toISOString().slice(0,10)};zipMessage=S.location.city+', '+S.location.state+' · '+zip+'. Ready to record local quotes.';save(false)}catch(e){if(S.zip!==zip)return;zipMessage='ZIP '+zip+' saved. '+(e.message==='notfound'?'Place lookup has no match.':'Place lookup is unavailable; retry when online.')+' You can still record quotes for this ZIP.'}finally{clearTimeout(timeout);if(zipAbort===controller){zipLoading=false;refreshLocation()}}}
function refreshLocation(){if(S.step===0&&location.hash==='#studio')renderControls();if(location.hash==='#pricing')renderPricing();bindLocationFields()}
function pathInspector(p){return `<h3>${esc(p.name)}</h3><span class="object-badge">${pathLength(p).toFixed(1)} ft route</span><label class="field">Path material<select id="edit-path-material">${Object.entries(MATERIALS).map(([k,m])=>`<option value="${k}" ${p.material===k?'selected':''}>${m.name}</option>`).join('')}</select></label><label class="field">Width · ft<input id="edit-path-width" type="number" min=".5" max="20" step=".5" value="${p.width}"></label><p class="note">Surface quantities use the part inside the garden, excluding built footprints. Edit waypoints below.</p>${pointFields(p.points,'pv')}<button class="text-btn delete-photo" id="delete-path">Remove walkway</button>`}
function pointFields(points,prefix){return points.map((p,j)=>`<div class="vertex-row"><span>${j+1}</span><input data-${prefix}="${j}" data-axis="x" type="number" aria-label="Point ${j+1} X feet" min="0" max="${S.width}" step=".1" value="${(p.x*S.width).toFixed(1)}"><input data-${prefix}="${j}" data-axis="y" type="number" aria-label="Point ${j+1} Y feet" min="0" max="${S.depth}" step=".1" value="${(p.y*S.depth).toFixed(1)}"></div>`).join('')}
function bindPathInspector(p){$('#edit-path-material').onchange=e=>change(()=>p.material=e.target.value);$('#edit-path-width').onchange=e=>{const v=+e.target.value;if(v>=.5&&v<=20)change(()=>p.width=v);else renderInspector()};$$('[data-pv]').forEach(inp=>inp.onchange=()=>{const a=inp.dataset.axis,max=a==='x'?S.width:S.depth,v=+inp.value;if(Number.isFinite(v)&&v>=0&&v<=max)change(()=>p.points[+inp.dataset.pv][a]=v/max);else renderInspector()});$('#delete-path').onclick=()=>change(()=>{S.paths=S.paths.filter(x=>x.id!==p.id);selection=null},{controls:true})}
function plantDetails(c){if(c.type!=='plant')return'';const mismatch=c.sun&&S.sun!=='unknown'&&!c.sun.includes(S.sun);return `<div class="plant-care"><span class="eyebrow">PLANTING NOTES</span><p>${esc(c.care||'Site suitability, nursery stock and cultivar are not verified. Footprint is a planning allowance; confirm mature dimensions before ordering.')}</p>${mismatch?'<p class="compatibility-note">Your recorded sunlight differs from the sourced preference. Review the plant choice before ordering.</p>':''}${c.source?`<a class="source-link" href="${c.source}" target="_blank" rel="noopener">NC State plant profile ↗</a>`:'<span class="note">Species / cultivar not yet confirmed</span>'}</div>`}
function constructionChecks(){const needed=[];if(S.items.some(i=>CATALOG[i.kind].group==='water'))needed.push(['Water features','Confirm site survey, excavation, pool barriers, hydraulics, bonding and permits.','https://www.cpsc.gov/safety-education/safety-guides/pools-and-spas/safety-barrier-guidelines-home-pools']);if(S.items.some(i=>CATALOG[i.kind].group==='structure'))needed.push(['Walls & raised platforms','Confirm boundaries, foundations, loads, drainage, access and any required structural design.','']);if(S.items.some(i=>CATALOG[i.kind].group==='kitchen'))needed.push(['Outdoor kitchen','Confirm appliance model, supports, manufacturer clearances, water/drainage, electrical and fuel requirements.','']);if(S.routes.length)needed.push(['Underground services','Confirm records, locate existing services and arrange the relevant professional design before digging.','https://www.enbridge.com/projects-and-infrastructure/public-awareness/safe-digging-and-damage-prevention/call-811']);return `<div class="professional-checks"><span class="eyebrow">YOUR PROJECT-SPECIFIC CHECKS</span>${needed.length?needed.map(([h,t,u])=>`<p><b>${h}</b><br>${t}${u?` <a class="source-link" href="${u}" target="_blank" rel="noopener">Reference ↗</a>`:''}</p>`).join(''):'<p class="note">Confirm site dimensions, drainage, plants and materials before ordering.</p>'}</div>`}
let activeQuoteKey=null;
function budgetView(){const e=estimate();$('#pricing-total').textContent=money(e.subtotal);const banner=$('.estimate-banner .eyebrow');banner.textContent='PARTIAL PLANNING TOTAL · '+e.unknown+' ITEMS STILL UNPRICED';$('.estimate-banner p').textContent='USD · '+(S.zip?'Quote market: ZIP '+S.zip+'. ':'Add a ZIP to record local quotes. ')+'Sample allowances and user-entered quotes are shown separately. No live retailer prices are connected.';$('#budget-table').innerHTML=`<div class="budget-locality">${locationFields('budget')}</div><div class="price-split"><div><span>ZIP-matched quotes</span><strong>${money(e.localTotal)}</strong></div><div><span>Demo allowances</span><strong>${money(e.demoTotal)}</strong></div><div><span>Awaiting quotes</span><strong>${e.unknown} items</strong></div></div><div class="price-row heading"><span>YOUR ELEMENTS & SCOPE</span><span>QUANTITY</span><span>COST / SOURCE</span></div>`+e.rows.map(r=>`<div class="price-row"><div>${esc(r.name)}<small>${esc(r.detail)}</small><span class="price-state ${r.priceState}">${r.priceState==='local'?'User-entered quote · ZIP '+S.zip:r.priceState==='demo'?'Demonstration allowance':'Quote required'}</span>${r.quote?`<small>${esc(r.quote.source)} · ${esc(r.quote.date)} · ${r.quote.scope==='installed'?'Supply & installation':'Supply / materials only'}${r.quote.url?` · <a href="${esc(r.quote.url)}" class="source-link" target="_blank" rel="noopener">Source ↗</a>`:''}</small>`:''}${r.stale?'<small class="compatibility-note">Previous quote has different quantities; reconfirm before applying.</small>':''}</div><span>${esc(r.qty)}</span><div class="price-cell"><strong>${r.amount===null?'Not priced':money(r.amount)}</strong><button class="text-btn" data-quote="${esc(r.key)}">${r.quote?'Edit local quote':'Add local quote'} ↗</button></div></div>`).join('')+`<div class="price-row"><div>Planning reserve<small>Based only on currently priced portions</small></div><span>${S.reserve}%</span><span>${money(e.reserve)}</span></div><div class="price-row total"><span>Partial plan + reserve</span><span></span><span>${money(e.total)}</span></div><p class="note">Garden ${e.area.toFixed(1)} sq ft · Soil ${e.soil.toFixed(1)} sq ft · Paths ${e.pathArea.toFixed(1)} sq ft · Built / water footprints ${e.occupied.toFixed(1)} sq ft. Areas use a clipped 120 × 120 sampling grid. Built footprints are excluded from ground quantities. Paths take priority over soil; newer paths take priority over older paths. No quantities count twice.</p>${e.rows.some(r=>r.quote?.scope==='installed')?'<p class="compatibility-note">Some quotes include installation. Check the separate labour row for overlapping scope before accepting the budget.</p>':''}${issueMarkup()}${constructionChecks()}`;$('#target-budget').value=S.target;$('#target-label').textContent=money(S.target);$('#reserve').value=S.reserve;$('#budget-advice').innerHTML=`<div class="advice">${e.total>S.target?'The priced portion exceeds your target by '+money(e.total-S.target)+'.':money(S.target-e.total)+' of your target is not yet allocated.'} ${e.unknown} lines are still unpriced; this is not a complete project estimate. Your design is never reduced automatically.</div>`;const tasks=[['Meet your patch','Measure, observe sunlight, record soil and map existing services.'],['Resolve the build','Confirm structural, pool, utility and appliance requirements; gather ZIP-specific quotes.'],['Ready, set, grow','Confirm product availability, permits and site conditions before ordering or digging.']];$('#tasks').innerHTML=tasks.map(([a,b],i)=>`<label class="task-row"><input type="checkbox" data-task="${i}" ${S.tasks[i]?'checked':''}><span>0${i+1} / ${a}<small>${b}</small></span></label>`).join('');$$('[data-task]').forEach(c=>c.onchange=()=>change(()=>S.tasks[+c.dataset.task]=c.checked));$('#task-progress').textContent=S.tasks.filter(Boolean).length+' / 3 LITTLE WINS';$$('[data-quote]').forEach(b=>b.onclick=()=>openQuote(b.dataset.quote));bindLocationFields()}
function openQuote(key){if(!/^\d{5}$/.test(S.zip)){notify('Add your five-digit ZIP on the budget page before recording a local quote.');$('.zip-input')?.focus();return}const row=estimate().rows.find(r=>r.key===key);if(!row)return;activeQuoteKey=key;const q=quoteFor(row);$('#quote-title').textContent=row.name;$('#quote-quantity').textContent=row.qty+' · ZIP '+S.zip+'. This amount covers this entire line at the current quantities.';$('#quote-amount').value=q?.amount??'';$('#quote-source').value=q?.source||'';$('#quote-date').value=q?.date||new Date().toISOString().slice(0,10);$('#quote-date').max=new Date().toISOString().slice(0,10);$('#quote-url').value=q?.url||'';$('#quote-scope').value=q?.scope||'materials';$('#quote-error').textContent='';$('#remove-quote').hidden=!q;$('#quote-dialog').showModal()}
function bindQuoteForm(){$('#quote-form').onsubmit=e=>{e.preventDefault();const row=estimate().rows.find(r=>r.key===activeQuoteKey);if(!row)return;const amount=+$('#quote-amount').value,source=$('#quote-source').value.trim(),date=$('#quote-date').value,url=$('#quote-url').value.trim(),scope=$('#quote-scope').value;if(!Number.isFinite(amount)||amount<0||amount>1e8||!source||!date||date>new Date().toISOString().slice(0,10)||url&&!/^https?:\/\//.test(url)){$('#quote-error').textContent='Enter an amount, source and valid quote date. Source links must start with https:// or http://.';return}change(()=>{S.quotes=S.quotes.filter(q=>!(q.key===row.key&&q.zip===S.zip));S.quotes.push({key:row.key,signature:row.signature,zip:S.zip,amount,source,date,url,scope})});$('#quote-dialog').close();notify('Local quote recorded for ZIP '+S.zip+'. It will not apply to a different ZIP or quantity.')};$('#remove-quote').onclick=()=>{change(()=>S.quotes=S.quotes.filter(q=>!(q.key===activeQuoteKey&&q.zip===S.zip)));$('#quote-dialog').close()}}
function footprintPoints(i){const rad=i.angle*Math.PI/180;const ring=CATALOG[i.kind].round?Array.from({length:32},(_,j)=>[Math.cos(j*Math.PI/16),Math.sin(j*Math.PI/16)]):[[-1,-1],[1,-1],[1,1],[-1,1]];return ring.map(([x,y])=>{const dx=x*i.w/2,dy=y*i.h/2;return{x:i.x+(dx*Math.cos(rad)-dy*Math.sin(rad))/S.width,y:i.y+(dx*Math.sin(rad)+dy*Math.cos(rad))/S.depth}})}
function facilityPerspective(i,project,b){const c=CATALOG[i.kind],ps=footprintPoints(i).map(project),water=c.group==='water',height=water?0:(i.height??c.height??1)*b.scale*.6,p=ps.map(q=>({x:q.x,y:q.y-height})),points=qs=>qs.map(q=>q.x+','+q.y).join(' '),fill=water?'#87afb1':i.kind.includes('wall')?'url(#floor-redbrick)':i.kind==='platform'?'url(#floor-cedar)':i.kind==='fence'?'#ad916d':'#c4b999';let out=`<g opacity="${S.night?.8:1}">`;if(height)out+=`<polygon points="${points([ps[1],ps[2],p[2],p[1]])}" fill="#98876c" stroke="#786e56"/><polygon points="${points([ps[2],ps[3],p[3],p[2]])}" fill="#ac9977" stroke="#786e56"/>`;out+=`<polygon points="${points(p)}" fill="${fill}" stroke="${water?'#c6d2bd':'#7e7d64'}" stroke-width="3"/>`;if(water){const center=project(i);out+=`<path d="M${center.x-i.w*b.scale*.2} ${center.y}q15-8 30 0t30 0" stroke="#d4e5d2" fill="none"/>`}return out+'</g>'}
function planningIssues(){const issues=[];for(const i of S.items){const c=CATALOG[i.kind];if(footprintPoints(i).some(p=>!inside(p)))issues.push(c.name+' extends beyond the drawn boundary.');if(c.occupies){for(const j of S.items){if(i.id===j.id||CATALOG[j.kind].type==='light')continue;if(pointInItem({x:j.x,y:j.y},i)||pointInItem({x:i.x,y:i.y},j))issues.push(c.name+' overlaps '+CATALOG[j.kind].name+'. Review footprint and access.')}for(const r of S.routes){if(r.points.some(p=>pointInItem(p,i))||r.points.slice(1).some((b,j)=>Array.from({length:20},(_,n)=>({x:r.points[j].x+(b.x-r.points[j].x)*n/20,y:r.points[j].y+(b.y-r.points[j].y)*n/20})).some(p=>pointInItem(p,i))))issues.push((UTILITY_TYPES[r.kind]?.name||'Service')+' crosses '+c.name+'. Coordinate the route with the relevant professional.')}}}return [...new Set(issues)]}
function issueMarkup(){const issues=planningIssues();return issues.length?`<details class="layout-issues" open><summary>${issues.length} layout checks to review</summary><ul>${issues.slice(0,12).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="note">Concept footprint checks only, not structural clearance or code checks.</p></details>`:''}
function renderPlanSelector(){const el=$('#plan-selection');if(!el)return;el.innerHTML='<option value="">Select a placed element…</option>'+S.items.map((i,j)=>`<option value="item:${esc(i.id)}">${j+1}. ${esc(CATALOG[i.kind].name)}</option>`).join('')+S.paths.map(p=>`<option value="path:${esc(p.id)}">${esc(p.name)}</option>`).join('')+S.zones.map(z=>`<option value="zone:${esc(z.id)}">${esc(z.name)}</option>`).join('')+S.routes.map(r=>`<option value="route:${esc(r.id)}">${esc(UTILITY_TYPES[r.kind]?.name||r.kind)} route</option>`).join('');el.value=selection?selection.type+':'+selection.id:'';el.onchange=()=>{const v=el.value,k=v.indexOf(':');selection=k<0?null:{type:v.slice(0,k),id:v.slice(k+1)};tool='select';draft=[];renderAll()}}
